#!/bin/bash
# run_pp4.sh RANK [extra vllm args]: start this node's part of the PP4 x TP4 server.
# Node k (Dev-(k+1)) is PP stage k; Dev-1 runs the API server, the others are headless.
RANK=$1; shift
IP=10.56.0.$((11 + RANK))
export PYTHONPATH=$HOME/v41/src
export CUDA_HOME=/usr/local/cuda-12.8 PATH=/usr/local/cuda-12.8/bin:$HOME/v41env/bin:$PATH
export VLLM_HOST_IP=$IP
export NCCL_SOCKET_IFNAME=ibp216s0 GLOO_SOCKET_IFNAME=ibp216s0
export NCCL_IB_HCA=mlx4_0:1 NCCL_IB_DISABLE=0 NCCL_NET_GDR_LEVEL=0
export VLLM_V41_NATIVE=1 VLLM_PP_LAYER_PARTITION=8,12,12,8
export VLLM_GGUF_EXPERT_CACHE_JIT=1 VLLM_V41K_LIB=$HOME/v41/src/benchmarks/deepseek_v41/v41k/build/v41k.so
export VLLM_V41_FP8_GEMV=1 VLLM_V41_EM=1 VLLM_V41_AR_ALLGATHER=1 VLLM_V41_PP_RANK0=1 VLLM_V41_FUSE_ATTN_PREP=1 VLLM_V41_FUSE_ATTN_POST=1 VLLM_V41_MARKOV_SHARD=1 VLLM_SM70_TP4_PUSH_ALLREDUCE=0 VLLM_V41_INLINE_DRAFTS=${VLLM_V41_INLINE_DRAFTS:-0} VLLM_V41_PP_SERIAL=${VLLM_V41_PP_SERIAL:-0} VLLM_V41_ASYNC=${VLLM_V41_ASYNC:-1} VLLM_V41_PP_TOKEN_NCCL=${VLLM_V41_PP_TOKEN_NCCL:-1} VLLM_V41_ROUTE_CUDA=${VLLM_V41_ROUTE_CUDA:-1} VLLM_V41_SHARED_STREAM=${VLLM_V41_SHARED_STREAM:-1} VLLM_V41_Q8_GROUPED=${VLLM_V41_Q8_GROUPED:-1} VLLM_V41_MOE_DEC=${VLLM_V41_MOE_DEC:-1} VLLM_V41_ATTN_DEC=${VLLM_V41_ATTN_DEC:-1} VLLM_V41_H16=${VLLM_V41_H16:-1} VLLM_V41_ATTN_RING=${VLLM_V41_ATTN_RING:-1} VLLM_V41_DEQUANT_MM_ROWS=${VLLM_V41_DEQUANT_MM_ROWS:-64} VLLM_V41_LL_AR=${VLLM_V41_LL_AR:-1} VLLM_V41_HC_SIDE=${VLLM_V41_HC_SIDE:-1} VLLM_FAST_ARGMAX=${VLLM_FAST_ARGMAX:-1} VLLM_V41_FUSED_CLIP=${VLLM_V41_FUSED_CLIP:-1} VLLM_V41_ATTN_RING_PREFILL=${VLLM_V41_ATTN_RING_PREFILL:-1} VLLM_V41_PP_SEND_DEFER=${VLLM_V41_PP_SEND_DEFER:-1} VLLM_V41_PP_RECV_EARLY=${VLLM_V41_PP_RECV_EARLY:-0}
# Fixed-DSpark5 decode paths; prefill receive uses the main stream by default.
export VLLM_V41_ATTN_RING_POST=${VLLM_V41_ATTN_RING_POST:-1}
export VLLM_V41_PREP_REGS=${VLLM_V41_PREP_REGS:-1}
export VLLM_V41_GREEDY_VERIFY=${VLLM_V41_GREEDY_VERIFY:-1}
export VLLM_V41_ROUTE_MATCH=${VLLM_V41_ROUTE_MATCH:-1}
export VLLM_V41_W13_SWIGLU=${VLLM_V41_W13_SWIGLU:-1}
export VLLM_WORKER_MULTIPROC_METHOD=spawn
ARGS="--config ${V41_CONFIG:-$HOME/v41/serve-native-pp4.yaml} --nnodes 4 --node-rank $RANK --master-addr 10.56.0.11 --master-port 29511"
[ "$RANK" != 0 ] && ARGS="$ARGS --headless"
exec $HOME/v41env/bin/python -m vllm.entrypoints.cli.main serve $ARGS ${V41_ARGS---async-scheduling} "$@"
